import { expect, it, vi } from \"vitest\";
vi.mock(\"@/lib/id\", () => import(\"../server/_support/doubles/id\"));
vi.mock(\"@/lib/logger\", async () => (await import(\"../server/_support/doubles/misc\")).loggerModule);
vi.mock(\"@/lib/rate-limit\", async () => (await import(\"../server/_support/doubles/misc\")).rateLimitModule);
import { createTenant, issueInput, useTemporaryDatabase } from \"../server/_support/fixtures\";
import * as issues from \"@/server/services/issue-service\";
import * as comments from \"@/server/services/comment-service\";
import * as projects from \"@/server/services/project-service\";
import * as search from \"@/server/services/search-service\";
import * as repo from \"@/server/repositories/search-repository\";
import { runSearchReindexJob } from \"@/server/jobs/search-reindex-job\";
import { getDb, searchIndex } from \"@/server/db\";
it(\"checks visibility, complete pagination, stale cleanup and tenant isolation\", async () => {
  const cleanup = await useTemporaryDatabase();
  const off = search.registerSearchListeners();
  try {
    const t = await createTenant(\"visibility\");
    const other = await createTenant(\"untouched\");
    await search.indexProject(other.org.id, other.project);
    const otherBefore = getDb().select().from(searchIndex).all().filter(r => r.orgId === other.org.id);
    await search.indexProject(t.org.id, t.project);
    const issue = await issues.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    const comment = await comments.createComment(t.actors.member, {orgId:t.org.id,issueId:issue.id,body:\"before\",parentId:null,mentionedUserIds:[]});
    for (let n=0;n<101;n++) {
      await issues.createIssue(t.actors.member, issueInput(t.org.id,t.project.id));
      await comments.createComment(t.actors.member,{orgId:t.org.id,issueId:issue.id,body:\"extra\",parentId:null,mentionedUserIds:[]});
    }
    const archived = await issues.createIssue(t.actors.member, issueInput(t.org.id,t.project.id));
    await comments.createComment(t.actors.member,{orgId:t.org.id,issueId:archived.id,body:\"archived\",parentId:null,mentionedUserIds:[]});
    await issues.archiveIssue(t.actors.member,t.org.id,archived.id);
    expect(await repo.countIndexed(t.org.id)).toBe(205);
    await projects.archiveProject(t.actors.admin,{orgId:t.org.id,projectId:t.project.id,archiveIssues:false});
    expect(await repo.countIndexed(t.org.id)).toBe(0);
    await comments.updateComment(t.actors.member,{orgId:t.org.id,commentId:comment.id,body:\"edited hidden\"});
    await issues.updateIssue(t.actors.member,{orgId:t.org.id,issueId:issue.id,title:\"edited hidden\"});
    const later = await comments.createComment(t.actors.member,{orgId:t.org.id,issueId:issue.id,body:\"later\",parentId:null,mentionedUserIds:[]});
    expect(await repo.countIndexed(t.org.id)).toBe(0);
    expect((await runSearchReindexJob(t.org.id)).failed).toBe(0);
    expect(await repo.countIndexed(t.org.id)).toBe(0);
    await projects.restoreProject(t.actors.admin,t.org.id,t.project.id);
    expect(await repo.countIndexed(t.org.id)).toBe(206);
    expect((await repo.searchDocuments({orgId:t.org.id,q:\"edited hidden\",kinds:[],limit:100,cursor:null})).total).toBe(2);
    await comments.deleteComment(t.actors.member,{orgId:t.org.id,commentId:later.id});
    getDb().insert(searchIndex).values({id:\"orphan\",orgId:t.org.id,subjectKind:\"issue\",subjectId:\"missing\",projectId:t.project.id,content:\"orphan\",indexedAt:new Date().toISOString()}).run();
    expect((await repo.searchDocuments({orgId:t.org.id,q:\"orphan\",kinds:[],limit:100,cursor:null})).total).toBe(0);
    expect((await runSearchReindexJob(t.org.id)).failed).toBe(0);
    expect(await repo.countIndexed(t.org.id)).toBe(205);
    expect(getDb().select().from(searchIndex).all().filter(r => r.orgId === other.org.id)).toEqual(otherBefore);
    await projects.archiveProject(t.actors.admin,{orgId:t.org.id,projectId:t.project.id,archiveIssues:true});
    await projects.restoreProject(t.actors.admin,t.org.id,t.project.id);
    expect(await repo.countIndexed(t.org.id)).toBe(1);
  } finally { off(); cleanup(); }
});
EOF
